import{_ as d,a0 as o,w as p,s as l,ao as r,I as i,x as s,a1 as t,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"试试动态窗口管理器 dwm 吧 | LCTT x X-CMD","titleTemplate":false,"description":"试试动态窗口管理器 dwm 吧 | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"试试动态窗口管理器 dwm 吧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"试试动态窗口管理器 dwm 吧 | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190318 Let-s try dwm - dynamic window manager","title":"试试动态窗口管理器 dwm 吧","tag":"201908","desc":""},"relativePath":"201908/20190318 Let-s try dwm - dynamic window manager.md","filePath":"[post].md"}'),c={name:"201908/20190318 Let-s try dwm - dynamic window manager.md"};function m(h,a,g,u,k,f){const e=o("Link");return p(),l("div",null,[a[18]||(a[18]=r(`<h1 id="试试动态窗口管理器-dwm-吧" tabindex="-1">试试动态窗口管理器 dwm 吧 <a class="header-anchor" href="#试试动态窗口管理器-dwm-吧" aria-label="Permalink to “试试动态窗口管理器 dwm 吧”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/03/dwm-magazine-image-816x345.png" alt=""></p><p>如果你崇尚效率和极简主义，并且正在为你的 Linux 桌面寻找新的窗口管理器，那么你应该尝试一下<ruby>动态窗口管理器<rt>dynamic window manager</rt></ruby> dwm。以不到 2000 标准行的代码写就的 dwm，是一个速度极快而功能强大，且可高度定制的窗口管理器。</p><p>你可以在平铺、单片和浮动布局之间动态选择，使用标签将窗口组织到多个工作区，并使用键盘快捷键快速导航。本文将帮助你开始使用 dwm。</p><h3 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to “安装”">​</a></h3><p>要在 Fedora 上安装 dwm，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install dwm dwm-user</span></span></code></pre></div><p><code>dwm</code> 包会安装窗口管理器本身，<code>dwm-user</code> 包显著简化了配置，本文稍后将对此进行说明。</p><p>此外，为了能够在需要时锁定屏幕，我们还将安装 <code>slock</code>，这是一个简单的 X 显示锁屏。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install slock</span></span></code></pre></div><p>当然，你可以根据你的个人喜好使用其它的锁屏。</p><h3 id="快速入门" tabindex="-1">快速入门 <a class="header-anchor" href="#快速入门" aria-label="Permalink to “快速入门”">​</a></h3><p>要启动 dwm，在登录屏选择 “dwm-user” 选项。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/03/choosing-dwm-1024x469.png" alt=""></p><p>登录后，你将看到一个非常简单的桌面。事实上，顶部唯一的一个面板列出了代表工作空间的 9 个标签和一个代表窗户布局的 <code>[]=</code> 符号。</p><h4 id="启动应用" tabindex="-1">启动应用 <a class="header-anchor" href="#启动应用" aria-label="Permalink to “启动应用”">​</a></h4><p>在查看布局之前，首先启动一些应用程序，以便你可以随时使用布局。可以通过按 <code>Alt+p</code> 并键入应用程序的名称，然后回车来启动应用程序。还有一个快捷键 <code>Alt+Shift+Enter</code> 用于打开终端。</p><p>现在有一些应用程序正在运行了，请查看布局。</p><h4 id="布局" tabindex="-1">布局 <a class="header-anchor" href="#布局" aria-label="Permalink to “布局”">​</a></h4><p>默认情况下有三种布局：平铺布局，单片布局和浮动布局。</p><p>平铺布局由条形图上的 <code>[]=</code> 表示，它将窗口组织为两个主要区域：左侧为主区域，右侧为堆叠区。你可以按 <code>Alt+t</code> 激活平铺布局。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/03/dwm-desktop-1024x593.png" alt=""></p><p>平铺布局背后的想法是，主窗口放在主区域中，同时仍然可以看到堆叠区中的其他窗口。你可以根据需要在它们之间快速切换。</p><p>要在两个区域之间交换窗口，请将鼠标悬停在堆叠区中的一个窗口上，然后按 <code>Alt+Enter</code> 将其与主区域中的窗口交换。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/03/Screenshot-2019-03-15-at-11.12.32-1024x592.png" alt=""></p><p>单片布局由顶部栏上的 <code>[N]</code> 表示，可以使你的主窗口占据整个屏幕。你可以按 <code>Alt+m</code> 切换到它。</p><p>最后，浮动布局可让你自由移动和调整窗口大小。它的快捷方式是 <code>Alt+f</code>，顶栏上的符号是 <code>&gt;&lt;&gt;</code>。</p><h4 id="工作区和标签" tabindex="-1">工作区和标签 <a class="header-anchor" href="#工作区和标签" aria-label="Permalink to “工作区和标签”">​</a></h4><p>每个窗口都分配了一个顶部栏中列出的标签（1-9）。要查看特定标签，请使用鼠标单击其编号或按 <code>Alt+1..9</code>。你甚至可以使用鼠标右键单击其编号，一次查看多个标签。</p><p>通过使用鼠标突出显示后，并按 <code>Alt+Shift+1..9</code>，窗口可以在不同标签之间移动。</p><h3 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to “配置”">​</a></h3><p>为了使 dwm 尽可能简约，它不使用典型的配置文件。而是你需要修改代表配置的 C 语言头文件，并重新编译它。但是不要担心，在 Fedora 中你只需要简单地编辑主目录中的一个文件，而其他一切都会在后台发生，这要归功于 Fedora 的维护者提供的 <code>dwm-user</code> 包。</p><p>首先，你需要使用类似于以下的命令将文件复制到主目录中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir ~/.dwm</span></span>
<span class="line"><span>$ cp /usr/src/dwm-VERSION-RELEASE/config.def.h ~/.dwm/config.h</span></span></code></pre></div><p>你可以通过运行 <code>man dwm-start</code> 来获取确切的路径。</p><p>其次，只需编辑 <code>~/.dwm/config.h</code> 文件。例如，让我们配置一个新的快捷方式：通过按 <code>Alt+Shift+L</code> 来锁定屏幕。</p><p>考虑到我们已经安装了本文前面提到的 <code>slock</code> 包，我们需要在文件中添加以下两行以使其工作：</p><p>在 <code>/* commands */</code> 注释下，添加：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>static const char *slockcmd[] = { &quot;slock&quot;, NULL };</span></span></code></pre></div><p>添加下列行到 <code>static Key keys[]</code> 中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{ MODKEY|ShiftMask, XK_l, spawn, {.v = slockcmd } },</span></span></code></pre></div><p>最终，它应该看起来如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>...</span></span>
<span class="line"><span> /* commands */</span></span>
<span class="line"><span> static char dmenumon[2] = &quot;0&quot;; /* component of dmenucmd, manipulated in spawn() */</span></span>
<span class="line"><span> static const char *dmenucmd[] = { &quot;dmenu_run&quot;, &quot;-m&quot;, dmenumon, &quot;-fn&quot;, dmenufont, &quot;-nb&quot;, normbgcolor, &quot;-nf&quot;, normfgcolor, &quot;-sb&quot;, selbgcolor, &quot;-sf&quot;, selfgcolor, NULL };</span></span>
<span class="line"><span> static const char *termcmd[]  = { &quot;st&quot;, NULL };</span></span>
<span class="line"><span> static const char *slockcmd[] = { &quot;slock&quot;, NULL };</span></span>
<span class="line"><span></span></span>
<span class="line"><span> static Key keys[] = {</span></span>
<span class="line"><span>     /* modifier                     key        function        argument */</span></span>
<span class="line"><span>     { MODKEY|ShiftMask,             XK_l,      spawn,          {.v = slockcmd } },</span></span>
<span class="line"><span>     { MODKEY,                       XK_p,      spawn,          {.v = dmenucmd } },</span></span>
<span class="line"><span>     { MODKEY|ShiftMask,             XK_Return, spawn,          {.v = termcmd } },</span></span>
<span class="line"><span> ...</span></span></code></pre></div><p>保存文件。</p><p>最后，按 <code>Alt+Shift+q</code> 注销，然后重新登录。<code>dwm-user</code> 包提供的脚本将识别你已更改主目录中的<code>config.h</code> 文件，并会在登录时重新编译 dwm。因为 dwm 非常小，它快到你甚至都不会注意到它重新编译了。</p><p>你现在可以尝试按 <code>Alt+Shift+L</code> 锁定屏幕，然后输入密码并按回车键再次登录。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>如果你崇尚极简主义并想要一个非常快速而功能强大的窗口管理器，dwm 可能正是你一直在寻找的。但是，它可能不适合初学者，你可能需要做许多其他配置才能按照你的喜好进行配置。</p>`,48)),i("p",null,[a[1]||(a[1]=s("要了解有关 dwm 的更多信息，请参阅该项目的主页： ",-1)),t(e,{href:"https://dwm.suckless.org/"},{default:n(()=>[...a[0]||(a[0]=[s("https://dwm.suckless.org/",-1)])]),_:1}),a[2]||(a[2]=s("。",-1))]),a[19]||(a[19]=i("hr",null,null,-1)),i("p",null,[a[4]||(a[4]=s("via: ",-1)),t(e,{href:"https://fedoramagazine.org/lets-try-dwm-dynamic-window-manger/"},{default:n(()=>[...a[3]||(a[3]=[s("https://fedoramagazine.org/lets-try-dwm-dynamic-window-manger/",-1)])]),_:1})]),i("p",null,[a[9]||(a[9]=s("作者：",-1)),t(e,{href:"https://fedoramagazine.org/author/asamalik/"},{default:n(()=>[...a[5]||(a[5]=[s("Adam Šamalík",-1)])]),_:1}),a[10]||(a[10]=s(" 选题：",-1)),t(e,{href:"https://github.com/lujun9972"},{default:n(()=>[...a[6]||(a[6]=[s("lujun9972",-1)])]),_:1}),a[11]||(a[11]=s(" 译者：",-1)),t(e,{href:"https://github.com/wxy"},{default:n(()=>[...a[7]||(a[7]=[s("wxy",-1)])]),_:1}),a[12]||(a[12]=s(" 校对：",-1)),t(e,{href:"https://github.com/wxy"},{default:n(()=>[...a[8]||(a[8]=[s("wxy",-1)])]),_:1})]),i("p",null,[a[15]||(a[15]=s("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...a[13]||(a[13]=[s("LCTT",-1)])]),_:1}),a[16]||(a[16]=s(" 原创编译，",-1)),t(e,{href:"https://linux.cn/"},{default:n(()=>[...a[14]||(a[14]=[s("Linux中国",-1)])]),_:1}),a[17]||(a[17]=s(" 荣誉推出",-1))])])}const x=d(c,[["render",m]]);export{y as __pageData,x as default};
